"""Efficiency playbooks: short, verifiable strategies. All ship as 'unbenchmarked' until a measured A/B run is recorded
(`assetrag bench playbooks --execute`); none is claimed to improve results without that evidence."""


def P(key, title, when, benefit, steps, risks, verify, anti=()):
    return dict(key=key, title=title, when_to_use=when, benefit=benefit, steps=steps, risks=risks, verify=verify, anti_patterns=list(anti),
                benchmark_status="unbenchmarked")


